# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def stud(ident, last, first, sect, mail):
    return Student(ident, last, first, sect, mail)


class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            stud("2", "Young", "Al", "B", "al@x.io"),
            stud("1", "Abbott", "Beth", "A1", "b@x.org")
        ])
        self.assertEqual(rows, [
            "Abbott, Beth  A1  b@x.org",
            "Young, Al     B   al@x.io"
        ])

    def test_sort_ignores_case(self):
        rows = contact_rows([
            stud("1", "zed", "Amy", "A", "a@x.org"),
            stud("2", "Adams", "Bob", "A", "b@x.org")
        ])
        self.assertTrue(rows[0].startswith("Adams"))

    def test_missing_email_names_the_student(self):
        pupils = [
            stud("1", "Abbott", "Beth", "A", "b@x.org"),
            stud("2", "Young", "Al", "A", None)
        ]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(pupils)
        self.assertIn("Young, Al", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        pupils = [stud("1", "Abbott", "Beth", "A", "  ")]
        with self.assertRaises(ProjectError):
            contact_rows(pupils)

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
